];

const DIMS = [
  { key: 'gdp_per_capita_usd',         label: 'GDP per Capita',     unit: 'USD',   scale: 'log' },
  { key: 'hdi',                         label: 'HDI',                unit: '0–1',   scale: 'linear' },
  { key: 'freedom_index',               label: 'Freedom Index',      unit: '0–100', scale: 'linear' },
  { key: 'corruption_perceptions_index',label: 'CPI',                unit: '0–100', scale: 'linear' },
  { key: 'co2_emissions_per_capita_tons',label: 'CO₂ / Capita',     unit: 'tons',  scale: 'log' },
  { key: 'military_expenditure_pct_gdp', label: 'Military % GDP',   unit: '%',     scale: 'linear' },
  { key: 'internet_penetration_pct',    label: 'Internet',           unit: '%',     scale: 'linear' }
];

const GROUP_COLORS = {
  'High':         '#4fc3a1',
  'Upper-Middle': '#f6a623',
  'Lower-Middle': '#e05c7a',
  'Low':          '#8b9cbf'
};

const GROUPS = ['High', 'Upper-Middle', 'Lower-Middle', 'Low'];

// Outlier highlights (countries that deviate from group norms)
const OUTLIERS = new Set(['Saudi Arabia', 'United Arab Emirates', 'United States', 'Australia', 'Russia']);

function getMin(key) { return Math.min(...DATA.map(d => d[key])); }
function getMax(key) { return Math.max(...DATA.map(d => d[key])); }

// Scale value [0,1] within dimension
function normalize(val, dim) {
  const mn = getMin(dim.key), mx = getMax(dim.key);
  if (dim.scale === 'log') {
    return (Math.log(val) - Math.log(mn)) / (Math.log(mx) - Math.log(mn));
  }
  return (val - mn) / (mx - mn);
}

// Format tick values
function fmtTick(val, dim) {
  if (dim.key === 'gdp_per_capita_usd') {
    return val >= 1000 ? `$${(val/1000).toFixed(0)}k` : `$${val}`;
  }
  if (dim.key === 'hdi') return val.toFixed(2);
  if (dim.key === 'co2_emissions_per_capita_tons') return val.toFixed(1);
  if (dim.key === 'military_expenditure_pct_gdp') return val.toFixed(1) + '%';
  return Math.round(val);
}

function fmtVal(val, dim) {
  if (dim.key === 'gdp_per_capita_usd') return '$' + val.toLocaleString();
  if (dim.key === 'hdi') return val.toFixed(3);
  if (dim.key === 'co2_emissions_per_capita_tons') return val + ' t';
  if (dim.key === 'military_expenditure_pct_gdp') return val + '%';
  if (dim.key === 'internet_penetration_pct') return val + '%';
  return val;
}

function fmtDimLabel(key) {
  return {
    gdp_per_capita_usd: 'GDP per Capita',
    hdi: 'HDI',
    freedom_index: 'Freedom Index',
    corruption_perceptions_index: 'CPI',
    co2_emissions_per_capita_tons: 'CO₂/Capita',
    military_expenditure_pct_gdp: 'Military % GDP',
    internet_penetration_pct: 'Internet %'
  }[key] || key;
}

function render() {
  const svg = document.getElementById('parallel-chart');
  const W = svg.parentElement.clientWidth - 48;
  const H = 480;
  const PAD_TOP = 64;
  const PAD_BOT = 32;
  const PAD_L = 30;
  const PAD_R = 30;
  const chartH = H - PAD_TOP - PAD_BOT;
  const numAxes = DIMS.length;
  const axisStep = (W - PAD_L - PAD_R) / (numAxes - 1);

  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  svg.setAttribute('width', W);
  svg.setAttribute('height', H);
  svg.innerHTML = '';

  const ns = 'http://www.w3.org/2000/svg';

  function axisX(i) { return PAD_L + i * axisStep; }
  function valueY(val, dim) {
    return PAD_TOP + (1 - normalize(val, dim)) * chartH;
  }

  // --- Draw background axis bands (subtle) ---
  DIMS.forEach((dim, i) => {
    if (i % 2 === 0) {
      const band = document.createElementNS(ns, 'rect');
      band.setAttribute('x', axisX(i) - axisStep / 2);
      band.setAttribute('y', PAD_TOP - 12);
      band.setAttribute('width', axisStep);
      band.setAttribute('height', chartH + 24);
      band.setAttribute('fill', 'rgba(255,255,255,0.015)');
      band.setAttribute('rx', '4');
      svg.appendChild(band);
    }
  });

  // --- Draw polylines, low/medium opacity ---
  // Render in order: Low, Lower-Middle, Upper-Middle, High
  const renderOrder = ['Low', 'Lower-Middle', 'Upper-Middle', 'High'];
  const paths = [];

  renderOrder.forEach(group => {
    const groupData = DATA.filter(d => d.income_group === group);
    groupData.forEach(d => {
      const pts = DIMS.map((dim, i) => `${axisX(i)},${valueY(d[dim.key], dim)}`).join(' ');
      const polyline = document.createElementNS(ns, 'polyline');
      polyline.setAttribute('points', pts);
      polyline.setAttribute('fill', 'none');
      const col = GROUP_COLORS[group];
      const isOutlier = OUTLIERS.has(d.country);
      polyline.setAttribute('stroke', col);
      polyline.setAttribute('stroke-width', isOutlier ? '2.5' : '1.5');
      polyline.setAttribute('stroke-opacity', isOutlier ? '0.92' : '0.55');
      polyline.setAttribute('stroke-linejoin', 'round');
      polyline.setAttribute('stroke-linecap', 'round');
      polyline.dataset.country = d.country;
      polyline.dataset.group = group;
