      const tl = document.createElementNS(ns, 'text');
      tl.setAttribute('x', x + 8);
      tl.setAttribute('y', ty + 3);
      tl.setAttribute('class', 'axis-tick');
      tl.setAttribute('fill', '#545870');
      tl.setAttribute('font-family', "'IBM Plex Mono', monospace");
      tl.setAttribute('font-size', '9');
      tl.textContent = fmtTick(tv, dim);
