    const unit = document.createElementNS(ns, 'text');
    unit.setAttribute('x', x);
    unit.setAttribute('y', PAD_TOP - 10);
    unit.setAttribute('text-anchor', 'middle');
    unit.setAttribute('fill', '#404560');
    unit.setAttribute('font-family', "'IBM Plex Mono', monospace");
    unit.setAttribute('font-size', '8');
    unit.textContent = dim.unit;
