  // --- Outlier labels ---
  const labeledOutliers = ['Saudi Arabia', 'United Arab Emirates', 'United States', 'Norway', 'Russia'];
  labeledOutliers.forEach(name => {
    const d = DATA.find(x => x.country === name);
    if (!d) return;
    // Place label at CO2 axis position (index 4), shifted up
    const dimIdx = 4;
    const x = axisX(dimIdx) + (name === 'Norway' ? -6 : 6);
    const y = valueY(d[DIMS[dimIdx].key], DIMS[dimIdx]) - 7;
    const lbl = document.createElementNS(ns, 'text');
    lbl.setAttribute('x', x);
    lbl.setAttribute('y', y);
    lbl.setAttribute('fill', GROUP_COLORS[d.income_group]);
    lbl.setAttribute('font-family', "'IBM Plex Sans', sans-serif");
    lbl.setAttribute('font-size', '9.5');
    lbl.setAttribute('opacity', '0.8');
    lbl.setAttribute('text-anchor', name === 'Norway' ? 'end' : 'start');
    lbl.textContent = name.replace('United Arab Emirates', 'UAE').replace('United States', 'USA');
    svg.appendChild(lbl);
  });

  // --- Interaction ---
  const tooltip = document.getElementById('tooltip');
  let highlighted = null;

  paths.forEach(({ el, data, group }) => {
    el.addEventListener('mouseenter', (e) => {
      // Dim all others
      paths.forEach(p => {
