            <span>${fmtDimLabel(dim.key)}</span>
            <span class="tooltip-val">${fmtVal(data[dim.key], dim)}</span>
          </div>`).join('')}
      `;
      tooltip.classList.add('visible');
      highlighted = data.country;
    });

    el.addEventListener('mousemove', (e) => {
      const x = e.clientX + 16;
      const y = e.clientY - 20;
      const tw = 220;
      tooltip.style.left = (x + tw > window.innerWidth ? x - tw - 32 : x) + 'px';
      tooltip.style.top = y + 'px';
    });

    el.addEventListener('mouseleave', () => {
      const active = getActiveGroups();
      paths.forEach(p => {
        if (active.has(p.group)) {
          const isOutlier = OUTLIERS.has(p.data.country);
          p.el.setAttribute('stroke-opacity', isOutlier ? '0.92' : '0.55');
          p.el.setAttribute('stroke-width', isOutlier ? '2.5' : '1.5');
