  // Legend
  const legend = document.getElementById('legend');
  legend.innerHTML = '';
  const activeGroups = new Set(GROUPS);

  function getActiveGroups() { return activeGroups; }

  GROUPS.forEach(group => {
    const item = document.createElement('div');
    item.className = 'legend-item';
    item.dataset.group = group;
    item.innerHTML = `
      <div class="legend-swatch" style="background:${GROUP_COLORS[group]}"></div>
      <span>${group} Income</span>
    `;
    item.addEventListener('click', () => {
      if (activeGroups.has(group)) {
        if (activeGroups.size === 1) return; // Keep at least 1
        activeGroups.delete(group);
        item.classList.add('dimmed');
      } else {
        activeGroups.add(group);
        item.classList.remove('dimmed');
      }
      // Update line visibility
      paths.forEach(p => {
        if (activeGroups.has(p.group)) {
          const isOutlier = OUTLIERS.has(p.data.country);
          p.el.setAttribute('stroke-opacity', isOutlier ? '0.92' : '0.55');
        } else {
          p.el.setAttribute('stroke-opacity', '0');
        }
      });
    });
    legend.appendChild(item);
  });
}

window.addEventListener('load', render);
window.addEventListener('resize', render);
</script>

